async function adminFetch(url,options={}){const controller=new AbortController();const external=options.signal;const abort=()=>controller.abort(external?.reason);if(external?.aborted)abort();else external?.addEventListener('abort',abort,{once:true});const deadline=setTimeout(()=>controller.abort(),60000);try{const response=await fetch(url,{...options,signal:controller.signal});const bytes=await response.arrayBuffer();return {ok:response.ok,status:response.status,json:async()=>JSON.parse(new TextDecoder().decode(bytes))}}finally{clearTimeout(deadline);external?.removeEventListener('abort',abort)}}
let institutionalTimezone="America/Mexico_City";
// CONFIGURACIÓN Y ACCESO A DATOS: valores de referencia y funciones auxiliares de la vista administrativa.
