let centralAdminData=null;
let adminLoadGeneration=0;
function adminRead(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v??fallback}catch(e){return fallback}}
function adminWrite(key,value){localStorage.setItem(key,JSON.stringify(value))}
function adminRecords(){return centralAdminData?.advisories||[]}
function adminStudents(){return centralAdminData?.students||[]}
function adminUsers(){return centralAdminData?.users||[]}
function allAdvisors(){return adminUsers().filter(user=>user.rol!=='admin'&&user.role!=='admin')}
