async function saveAdvisor(event){event?.preventDefault();const form=admin$('#add-asesores'),nameInput=admin$('#newAdvisorName'),userInput=admin$('#newAdvisorUser'),passwordInput=admin$('#newAdvisorPassword'),nombre=String(nameInput?.value||'').trim(),usuario=String(userInput?.value||'').trim(),password=String(passwordInput?.value||''),message=admin$('#advisorFormMessage');if(message){message.textContent='';message.className='advisor-form-message'}if(!nombre||!usuario||password.length<10){const missing=password.length<10?'una contraseña de al menos 10 caracteres':!nombre?'el nombre completo':'el usuario';if(message){message.textContent=`Falta capturar ${missing}.`;message.classList.add('error')}alert(`Falta capturar ${missing}.`);return}const button=admin$('#saveAdvisorBtn');if(button){button.disabled=true;button.textContent='Guardando...'}try{const response=await adminFetch('/api/admin/users',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({fullName:nombre,username:usuario,password})});const payload=await response.json();if(!response.ok){if(message){message.textContent=payload.message||'No fue posible agregar al asesor.';message.classList.add('error')}return}await loadAdminData();form?.reset();if(message){message.textContent=`Asesor ${nombre} agregado correctamente con el usuario ${usuario}.`;message.classList.add('success')}alert(`Asesor ${nombre} agregado correctamente. Ya puede iniciar sesión con el usuario ${usuario}.`)}catch(error){if(message){message.textContent='No fue posible comunicarse con el servidor.';message.classList.add('error')}}finally{if(button){button.disabled=false;button.textContent='Agregar asesor'}}}
function schoolConfig(){const cfg=adminRead(ADMIN_KEYS.school,{schoolName:'NOMBRE DE LA INSTITUCIÓN',footer:'© 2025 Registro de Asesorías Académicas. Todos los derechos reservados.',version:'1.7.54'});cfg.version='1.7.54';return cfg}
function catalogs(){const c=adminRead(ADMIN_KEYS.catalogs,defaultCatalogs);return {...defaultCatalogs,...c}}
function periods(){if(centralAdminData?.periods?.length)return centralAdminData.periods.map(period=>period.name);const p=adminRead(ADMIN_KEYS.periods,[ADMIN_DEFAULT_PERIOD]);return Array.from(new Set(p.filter(Boolean)))}
function activePeriodName(){return centralAdminData?.periods?.find(period=>period.active!==false)?.name||periods()[0]||ADMIN_DEFAULT_PERIOD}
function adminPeriods(){return centralAdminData?.periods||[]}
function adminGroups(){return centralAdminData?.groups||[]}
function fmtAdmin(m){m=Math.max(0,Math.round(Number(m)||0));const h=Math.floor(m/60),min=m%60;if(h&&min)return `${h} h ${min} min`;if(h)return `${h} h`;return `${min} min`}
function escapeHTML(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
// FILTROS Y CÁLCULOS: selecciona cuatrimestre, aplica criterios y agrupa registros.
function selectedPeriod(){return admin$('#dashboardPeriod')?.value||activePeriodName()}
function periodRecords(period=selectedPeriod()){return adminRecords().filter(x=>x.periodo===period)}
function rangeMatch(x,r){const day=v=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:institutionalTimezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(v).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`};const d=new Date(x.inicioIso||x.creado),n=new Date();if(r==='all')return true;if(!Number.isFinite(+d))return false;const ds=day(d),ns=day(n);if(r==='day')return ds===ns;if(r==='month')return ds.slice(0,7)===ns.slice(0,7);if(r==='week'){const w=new Date(ns+'T00:00:00Z');w.setUTCDate(w.getUTCDate()-w.getUTCDay());return ds>=w.toISOString().slice(0,10)&&ds<=ns}return true}
function getAdminFiltered(){const rec=adminRecords();const period=admin$('adminPeriodFilter').value,range=admin$('adminRangeFilter').value,advisor=admin$('adminAdvisorFilter').value,career=admin$('adminCareerFilter').value,group=admin$('adminGroupFilter').value,subject=admin$('adminSubjectFilter').value,reason=admin$('adminReasonFilter').value,search=admin$('adminStudentSearch').value.trim().toLowerCase();return rec.filter(x=>(period==='all'||x.periodo===period)&&rangeMatch(x,range)&&(advisor==='all'||x.asesor===advisor)&&(career==='all'||x.carrera===career)&&(group==='all'||x.grupo===group)&&(subject==='all'||x.materia===subject)&&(reason==='all'||x.motivo===reason)&&(!search||String(x.matricula).toLowerCase().includes(search)||String(x.nombre).toLowerCase().includes(search)))}
function fillSelect(id,items,allLabel){const e=admin$(id);if(!e)return;const old=e.value;e.innerHTML=`<option value="all">${allLabel}</option>`+items.filter(x=>x&&x!=='Seleccione').map(x=>`<option value="${escapeHTML(x)}">${escapeHTML(x)}</option>`).join('');if(Array.from(e.options).some(o=>o.value===old))e.value=old}
function fillPeriodSelect(id,includeAll=false){const e=admin$(id);if(!e)return;const old=e.value;const p=periods();e.innerHTML=(includeAll?'<option value="all">Todos los cuatrimestres</option>':'')+p.map(x=>`<option value="${escapeHTML(x)}">${escapeHTML(x)}</option>`).join('');if(Array.from(e.options).some(o=>o.value===old))e.value=old;else if(!includeAll)e.value=activePeriodName()}
function fillAdminFilters(){const r=adminRecords(),c=catalogs();const uniq=k=>Array.from(new Set(r.map(x=>x[k]).filter(Boolean))).sort((a,b)=>String(a).localeCompare(String(b),'es')),advisorUsers=registeredAdvisors().map(user=>user.usuario).filter(Boolean).sort((a,b)=>String(a).localeCompare(String(b),'es'));fillPeriodSelect('adminPeriodFilter',true);fillSelect('adminAdvisorFilter',advisorUsers,'Todos');fillSelect('adminCareerFilter',uniq('carrera'),'Todas');fillSelect('adminGroupFilter',uniq('grupo'),'Todos');fillSelect('adminSubjectFilter',c.materias,'Todas');fillSelect('adminReasonFilter',c.motivos,'Todos')}
// DASHBOARD Y ESTADÍSTICAS: calcula indicadores y tablas por periodo.
function sumBy(rows,key){const out={};rows.forEach(x=>{const k=x[key]||'Sin dato';out[k]??={n:0,m:0};out[k].n++;out[k].m+=Number(x.duracionMinutos)||0});return out}
function renderRows(map,keys,empty='Sin registros.'){const entries=Object.entries(map);if(!entries.length)return `<tr><td colspan="${keys.length}">${empty}</td></tr>`;return entries.sort((a,b)=>b[1].m-a[1].m).map(([k,v])=>`<tr>${keys.map((_,i)=>i===0?`<td>${escapeHTML(k)}</td>`:i===1?`<td>${v.n}</td>`:`<td>${fmtAdmin(v.m)}</td>`).join('')}</tr>`).join('')}
function renderDashboard(){const p=selectedPeriod(),r=periodRecords(p),students=new Set(r.map(x=>x.matricula).filter(Boolean)),advisors=registeredAdvisors(),subjects=new Set(r.map(x=>x.materia).filter(x=>x&&x!=='Seleccione')),referrals=r.filter(x=>String(x.psico||'').toLowerCase().includes('sí')||String(x.psico||'').toLowerCase().includes('si')).length;admin$('#students').textContent=students.size||(!r.length&&p===ADMIN_DEFAULT_PERIOD?adminStudents().length:0);admin$('#sessions').textContent=r.length;admin$('#hours').textContent=fmtAdmin(r.reduce((t,x)=>t+(Number(x.duracionMinutos)||0),0));admin$('#advisors').textContent=advisors.length;admin$('#subjectsUsed').textContent=subjects.size;admin$('#referrals').textContent=referrals}
function renderStatistics(){const r=periodRecords(selectedPeriod());const bySubject=sumBy(r,'materia'),byReason=sumBy(r,'motivo'),byAdvisor=sumBy(r,'asesor'),bySex=sumBy(r,'sexo'),groupMap={};r.forEach(x=>{const k=`${x.carrera||'Sin carrera'} · ${x.grupo||'Sin grupo'}`;groupMap[k]??={n:0,m:0};groupMap[k].n++;groupMap[k].m+=Number(x.duracionMinutos)||0});const refMap={'Sí':{n:0,m:0},'No':{n:0,m:0}},refSex={'Hombre':{n:0,m:0},'Mujer':{n:0,m:0}};r.forEach(x=>{const yes=String(x.psico||'').toLowerCase().startsWith('s'),k=yes?'Sí':'No';refMap[k].n++;refMap[k].m+=Number(x.duracionMinutos)||0;if(yes){const sex=x.sexo||'Sin dato';refSex[sex]??={n:0,m:0};refSex[sex].n++;refSex[sex].m+=Number(x.duracionMinutos)||0}});admin$('#bySubject').innerHTML=renderRows(bySubject,['k','n','m']);admin$('#byReason').innerHTML=renderRows(byReason,['k','n','m']);admin$('#byAdvisor').innerHTML=renderRows(byAdvisor,['k','n','m']);admin$('#bySex').innerHTML=renderRows(bySex,['k','n','m']);admin$('#byReferralSex').innerHTML=renderRows(refSex,['k','n','m']);admin$('#byGroup').innerHTML=Object.entries(groupMap).sort((a,b)=>b[1].m-a[1].m).map(([k,v])=>{const parts=k.split(' · ');return `<tr><td>${escapeHTML(parts[0])}</td><td>${escapeHTML(parts[1]||'')}</td><td>${v.n}</td><td>${fmtAdmin(v.m)}</td></tr>`}).join('')||'<tr><td colspan="4">Sin registros.</td></tr>';admin$('#byReferral').innerHTML=renderRows(refMap,['k','n','m']);const all=adminRecords(),pm={};periods().forEach(name=>{pm[name]={n:0,m:0}});all.forEach(x=>{const k=x.periodo||'Sin cuatrimestre';pm[k]??={n:0,m:0};pm[k].n++;pm[k].m+=Number(x.duracionMinutos)||0});admin$('#byPeriod').innerHTML=renderRows(pm,['k','n','m'])}
function renderStudentSummary(){const r=periodRecords(selectedPeriod()),stu={};r.forEach(x=>{const k=x.matricula||'Sin matrícula';stu[k]??={nombre:x.nombre,n:0,m:0};stu[k].n++;stu[k].m+=Number(x.duracionMinutos)||0});const rows=Object.entries(stu).sort((a,b)=>b[1].m-a[1].m);admin$('#byStudent').innerHTML=rows.length?rows.map(([k,v])=>`<tr><td>${escapeHTML(k)}</td><td>${escapeHTML(v.nombre)}</td><td>${v.n}</td><td>${fmtAdmin(v.m)}</td></tr>`).join(''):'<tr><td colspan="4">Sin registros en este cuatrimestre.</td></tr>'}
// REPORTES: dibuja el historial administrativo con los filtros seleccionados.
function renderAdminReport(){const rows=getAdminFiltered(),body=admin$('#adminHistory tbody');body.innerHTML=rows.map(x=>`<tr><td>${escapeHTML(x.fecha)}</td><td>${escapeHTML(x.inicio)}</td><td>${escapeHTML(x.fin)}</td><td>${escapeHTML(x.matricula)}</td><td>${escapeHTML(x.nombre)}</td><td>${escapeHTML(x.sexo)}</td><td>${escapeHTML(x.carrera)}</td><td>${escapeHTML(x.grupo)}</td><td>${escapeHTML(x.materia)}</td><td>${escapeHTML(x.motivo)}</td><td>${escapeHTML(x.comentarios)}</td><td>${escapeHTML(x.asesor)}</td><td>${fmtAdmin(x.duracionMinutos)}</td><td>${escapeHTML(x.psico)}</td><td>${escapeHTML(x.periodo)}</td></tr>`).join('');admin$('#reportCount').textContent=`${rows.length} registro${rows.length===1?'':'s'}`;admin$('#reportHours').textContent=`Duración total: ${fmtAdmin(rows.reduce((t,x)=>t+(Number(x.duracionMinutos)||0),0))}`}
// CATÁLOGOS: representa alumnos, asesores, carreras, grupos, materias, motivos y cuatrimestres.
function renderCatalogStudents(filter=''){const q=filter.toLowerCase();const st=adminStudents().filter(x=>!q||String(x.matricula).toLowerCase().includes(q)||String(x.nombre).toLowerCase().includes(q));admin$('#catalogAlumnos').innerHTML=st.map(x=>`<tr><td>${escapeHTML(x.matricula)}</td><td>${escapeHTML(x.nombre)}</td><td>${escapeHTML(x.sexo)}</td><td>${escapeHTML(x.carrera)}</td><td>${escapeHTML(x.grupo)}</td><td>${escapeHTML(x.turno)}</td></tr>`).join('')||'<tr><td colspan="6">Sin alumnos.</td></tr>';admin$('#catAlumnosCount').textContent=`${st.length} de ${adminStudents().length} alumno${adminStudents().length===1?'':'s'}`}
