function renderCatalogPeriods(){const rows=adminPeriods();admin$('#catalogCuatrimestres').innerHTML=rows.map(period=>{const active=period.active!==false;return `<div class="catalog-item period-item"><div class="period-item-info"><strong>${escapeHTML(period.name)}</strong><small>${escapeHTML(formatPeriodDate(period.starts_on))} al ${escapeHTML(formatPeriodDate(period.ends_on))}</small></div><div class="period-actions"><span class="account-status ${active?'is-active':'is-inactive'}">${active?'Activo':'Inactivo'}</span><button class="${active?'danger':'secondary'} mini-btn period-status-btn" data-period-id="${escapeHTML(period.id)}" data-active="${active?'true':'false'}" data-period-name="${escapeHTML(period.name)}">${active?'Inactivar':'Reactivar'}</button></div></div>`}).join('')||'<div class="muted">Sin cuatrimestres registrados.</div>'}
