async function loadAdminData(){
  const generation=++adminLoadGeneration;
  const previousDashboardPeriod=centralAdminData?admin$('#dashboardPeriod')?.value:'';
  const response=await adminFetch('/api/admin/data?refresh='+Date.now(),{cache:'no-store',headers:{Accept:'application/json'}});
  if(generation!==adminLoadGeneration)return false;
  if(response.status===401||response.status===403){clearAdminView();showAdminLogin();return false}
  if(!response.ok)throw new Error('database_error');
  const payload=await response.json(),d=payload.data,c=d.catalogs;
  if(generation!==adminLoadGeneration)return false;
  if(!Array.isArray(d.advisories))throw new Error("incomplete_snapshot");
  institutionalTimezone=c.school?.timezone||"America/Mexico_City";
  const rows=d.advisories.map(x=>{const start=new Date(x.inicioIso),end=new Date(x.finIso);return{...x,fecha:start.toLocaleDateString('es-MX',{timeZone:institutionalTimezone}),inicio:start.toLocaleTimeString('es-MX',{timeZone:institutionalTimezone}),fin:end.toLocaleTimeString('es-MX',{timeZone:institutionalTimezone})}});
  centralAdminData={advisories:rows,students:d.students||[],users:d.users||[],periods:d.periodsAdmin||[],groups:d.groupsAdmin||[],catalogItems:d.catalogItems||{}};
  const cat={materias:(c.subjects||[]).map(x=>x.name),carreras:(c.careers||[]).map(x=>x.code),grupos:(c.groups||[]).map(x=>x.name),motivos:(c.reasons||[]).map(x=>x.name)};
  localStorage.setItem(ADMIN_KEYS.catalogs,JSON.stringify(cat));localStorage.setItem(ADMIN_KEYS.periods,JSON.stringify((d.periodsAdmin||c.periods||[]).map(x=>x.name)));
  localStorage.setItem(ADMIN_KEYS.school,JSON.stringify({schoolName:c.school?.school_name||'NOMBRE DE LA INSTITUCIÓN',footer:c.school?.footer_text||'© 2025 Registro de Asesorías Académicas. Todos los derechos reservados.',version:'1.7.54'}));
  const groupCareer=admin$('#newGroupCareer');if(groupCareer){const oldCareer=groupCareer.value;groupCareer.innerHTML='<option value="">Seleccione</option>'+(c.careers||[]).map(career=>`<option value="${escapeHTML(career.code)}">${escapeHTML(career.code)}</option>`).join('');if(Array.from(groupCareer.options).some(option=>option.value===oldCareer))groupCareer.value=oldCareer}
  if(payload.user){admin$('#adminCurrentUser').textContent='Administrador: '+payload.user.usuario;const account=centralAdminData.users.find(x=>x.usuario.toLowerCase()===payload.user.usuario.toLowerCase());admin$('#securityMsg').textContent=account&&!account.recuperacionConfigurada?'Importante: configure una clave de recuperación antes de cerrar la sesión.':''}
  applySchool();fillPeriodSelect('dashboardPeriod',false);if(!previousDashboardPeriod)admin$('#dashboardPeriod').value=activePeriodName();fillAdminFilters();renderAll();if(location.hash==='#bitacora')loadAuditPage();return true;
}
