async function saveAdminSecurity(){const currentPassword=admin$('#currentAdminPassword').value,newPassword=admin$('#newAdminPassword').value,confirmPassword=admin$('#confirmAdminPassword').value,recoveryCode=admin$('#newRecoveryCode').value,msg=admin$('#securityMsg');if(newPassword!==confirmPassword){msg.textContent='Las contraseñas nuevas no coinciden.';return}msg.textContent='Guardando...';try{const response=await adminFetch('/api/admin/security',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({currentPassword,newPassword,recoveryCode})});const payload=await response.json();msg.textContent=payload.message||'';if(response.ok){['currentAdminPassword','newAdminPassword','confirmAdminPassword','newRecoveryCode'].forEach(id=>admin$(id).value='');await loadAdminData();msg.textContent=payload.message||'Seguridad actualizada.'}}catch(error){msg.textContent='No fue posible comunicarse con el servidor.'}}

