let auditOffset=0,auditGeneration=0,restoreId=null;
async function loadAuditPage(){
 const generation=++auditGeneration,view=admin$('#auditView').value, cancelled=view==='cancelled',msg=admin$('#auditMessage');
 admin$('#auditRows').replaceChildren();msg.textContent='Cargando…';admin$('#auditPrev').disabled=admin$('#auditNext').disabled=true;
 try{const r=await adminFetch('/api/admin/audit?view='+view+'&offset='+auditOffset,{cache:'no-store'});if(generation!==auditGeneration)return;if(!r.ok)throw Error('No fue posible consultar la información.');const data=await r.json();if(generation!==auditGeneration)return;
 const headers=cancelled?['Alumno','Matrícula','Asesor','Materia','Cuatrimestre','Inicio','Duración (min)','Motivo','Acción']:['Fecha','Usuario','Acción','Entidad','Identificador','Detalles'];
 admin$('#auditHead').innerHTML='<tr>'+headers.map(x=>'<th>'+escapeHTML(x)+'</th>').join('')+'</tr>';
 for(const item of data.items){const tr=document.createElement('tr');const values=cancelled?[item.student_name,item.enrollment,item.advisor,item.subject,item.period,new Date(item.started_at).toLocaleString('es-MX',{timeZone:institutionalTimezone}),item.duration_minutes,item.reason||'No registrado']:[new Date(item.created_at).toLocaleString('es-MX',{timeZone:institutionalTimezone}),item.username,item.action,item.entity_type,item.entity_id];for(const v of values){const td=document.createElement('td');td.textContent=v??'—';tr.append(td)}const td=document.createElement('td');if(cancelled){const b=document.createElement('button');b.className='secondary';b.textContent='Restaurar';b.onclick=()=>{restoreId=item.id;admin$('#restoreLabel').textContent=item.student_name+' · '+item.period;admin$('#restoreReason').value='';admin$('#restoreMessage').textContent='';admin$('#restoreDialog').showModal()};td.append(b)}else{const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='Ver detalles';pre.textContent=JSON.stringify(item.details,null,2);pre.style.whiteSpace='pre-wrap';pre.style.overflowWrap='anywhere';details.append(summary,pre);td.append(details)}tr.append(td);admin$('#auditRows').append(tr)}
 msg.textContent=data.items.length?'':'No hay registros en esta página.';admin$('#auditPage').textContent='Página '+(auditOffset/50+1);admin$('#auditPrev').disabled=auditOffset===0;admin$('#auditNext').disabled=!data.hasMore;
 }catch(e){if(generation===auditGeneration)msg.textContent=e.message;}
}
document.addEventListener('DOMContentLoaded',()=>{
 admin$('#auditView').onchange=()=>{auditOffset=0;loadAuditPage()};admin$('#auditRefresh').onclick=()=>loadAuditPage();admin$('#auditPrev').onclick=()=>{auditOffset=Math.max(0,auditOffset-50);loadAuditPage()};admin$('#auditNext').onclick=()=>{auditOffset+=50;loadAuditPage()};admin$('#restoreCancel').onclick=()=>admin$('#restoreDialog').close();
 admin$('#restoreForm').onsubmit=async e=>{e.preventDefault();const b=admin$('#restoreSave'),msg=admin$('#restoreMessage');if(b.disabled)return;b.disabled=true;try{const r=await adminFetch('/api/admin/advisories/'+encodeURIComponent(restoreId)+'/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:admin$('#restoreReason').value.trim()})});const d=await r.json();if(!r.ok)throw Error(d.message||'No fue posible restaurar.');admin$('#restoreDialog').close();auditOffset=0;await loadAuditPage();try{await loadAdminData();admin$('#auditMessage').textContent='Asesoría restaurada.'}catch{admin$('#auditMessage').textContent='Asesoría restaurada; actualice los datos administrativos.'}}catch(e){msg.textContent=e.message}finally{b.disabled=false}};
});

function renderStudentFile(){const input=admin$('studentFileEnrollment'),summary=admin$('studentFileSummary'),table=admin$('studentFileRows');if(!input||!summary||!table)return;table.replaceChildren();summary.textContent='';const key=input.value.trim().toLowerCase();if(!key||!centralAdminData)return;const rows=adminRecords().filter(x=>String(x.matricula).toLowerCase()===key&&x.estado!=='CANCELADA');const student=adminStudents().find(x=>String(x.matricula).toLowerCase()===key);if(!rows.length&&!student){summary.textContent='No se encontró la matrícula.';return;}summary.textContent=`${student?.nombre||rows[0]?.nombre} · ${rows.length} asesorías · ${fmtAdmin(rows.reduce((n,x)=>n+(Number(x.duracionMinutos)||0),0))} · ${new Set(rows.map(x=>x.materia)).size} materias · ${new Set(rows.map(x=>x.periodo)).size} cuatrimestres`;for(const x of rows){const tr=table.insertRow();for(const value of [x.periodo,x.fecha,x.nombre,x.carrera,x.grupo,x.turno,x.sexo,x.materia,x.asesor,x.motivo,fmtAdmin(x.duracionMinutos)])tr.insertCell().textContent=value??'';}}
document.addEventListener('DOMContentLoaded',()=>{admin$('studentFileForm').addEventListener('submit',e=>{e.preventDefault();renderStudentFile()});});

// Indicadores descriptivos: cálculo puro, sin inferencias clínicas o de riesgo.
function calculateIndicators(records,period,threshold){
 const rows=records.filter(x=>x.estado!=='CANCELADA'&&(period==='all'||x.periodo===period));
 const students=new Map(), subjects=new Map(), reasons=new Map(), careers=new Map();
 let minutes=0, referrals=0;
 function add(map,key,m){const v=map.get(key)||{n:0,m:0};v.n++;v.m+=m;map.set(key,v)}
 for(const x of rows){const m=Math.max(0,Number(x.duracionMinutos)||0);minutes+=m;
  add(subjects,x.materia||'Sin dato',m);add(reasons,x.motivo||'Sin dato',m);add(careers,x.carrera||'Sin dato',m);
  const yes=/^s[ií]$/i.test(String(x.psico||'').trim());if(yes)referrals++;
  const key=String(x.matricula||'').trim().toLowerCase();if(!key)continue;
  const v=students.get(key)||{matricula:x.matricula,nombre:x.nombre,n:0,m:0,referrals:0};v.n++;v.m+=m;if(yes)v.referrals++;students.set(key,v);
 }
 const sort=(a,b)=>b.n-a.n||b.m-a.m;const ranked=map=>Array.from(map,([name,v])=>({name,...v})).sort(sort);
 const all=Array.from(students.values());return {sessions:rows.length,minutes,referrals,unique:all.length,recurrent:all.filter(x=>x.n>=threshold).sort(sort),referred:all.filter(x=>x.referrals>0).sort((a,b)=>b.referrals-a.referrals),subjects:ranked(subjects),reasons:ranked(reasons),careers:ranked(careers)};
}
function clearIndicators(){admin$('indicatorSummary').textContent='';for(const id of ['indicatorStudents','indicatorSubjects','indicatorReasons','indicatorCareers','indicatorReferrals'])admin$(id).replaceChildren()}
function renderIndicators(){clearIndicators();if(!centralAdminData)return;const d=calculateIndicators(adminRecords(),admin$('indicatorPeriod').value,Number(admin$('indicatorThreshold').value));
 admin$('indicatorSummary').textContent=`${d.sessions} asesorías · ${d.unique} alumnos identificados · ${fmtAdmin(d.minutes)} · ${d.recurrent.length} alumnos recurrentes · ${d.referred.length} alumnos canalizados · ${d.referrals} asesorías con canalización`;
 function draw(id,rows,cols){const body=admin$(id);if(!rows.length){const td=body.insertRow().insertCell();td.colSpan=cols;td.textContent='Sin registros.';return}for(const values of rows){const tr=body.insertRow();for(const v of values)tr.insertCell().textContent=v??''}}
 draw('indicatorStudents',d.recurrent.map(x=>[x.matricula,x.nombre,x.n,fmtAdmin(x.m)]),4);
 for(const [id,rows] of [['indicatorSubjects',d.subjects],['indicatorReasons',d.reasons],['indicatorCareers',d.careers]])draw(id,rows.map(x=>[x.name,x.n,fmtAdmin(x.m)]),3);
 draw('indicatorReferrals',d.referred.map(x=>[x.matricula,x.nombre,x.referrals]),3);
}
document.addEventListener('DOMContentLoaded',()=>{for(const id of ['indicatorPeriod','indicatorThreshold'])admin$(id).addEventListener('change',renderIndicators)});

// Comparación descriptiva: usa los mismos criterios que los indicadores.
function calculateComparison(records,base,target){
 const a=calculateIndicators(records,base,2),b=calculateIndicators(records,target,2);
 const delta=(name,x,y)=>({name,base:x,target:y,difference:y-x,percent:x===0?null:(y-x)/x*100});
 const merge=(left,right)=>{const l=new Map(left.map(x=>[x.name,x.n])),r=new Map(right.map(x=>[x.name,x.n]));return [...new Set([...l.keys(),...r.keys()])].map(k=>delta(k,l.get(k)||0,r.get(k)||0)).sort((x,y)=>y.target-x.target||y.base-x.base||x.name.localeCompare(y.name,'es'))};
 return {metrics:[delta('Asesorías',a.sessions,b.sessions),delta('Alumnos únicos identificados',a.unique,b.unique),delta('Tiempo de atención',a.minutes,b.minutes),delta('Materias atendidas',a.subjects.length,b.subjects.length)],subjects:merge(a.subjects,b.subjects),reasons:merge(a.reasons,b.reasons)};
}
function fillComparisonPeriods(){
 const a=admin$('compareBase'),b=admin$('compareTarget');const oldA=a.value,oldB=b.value;
 const names=[...new Set([...periods(),...adminRecords().map(x=>x.periodo)].filter(Boolean))];
 for(const [el,old] of [[a,oldA],[b,oldB]]){el.replaceChildren(new Option('Seleccione',''));for(const name of names)el.add(new Option(name,name));if(names.includes(old))el.value=old;}
 if(!b.value&&names.includes(activePeriodName()))b.value=activePeriodName();
}
function clearComparison(){admin$('compareMessage').textContent='';for(const id of ['compareMetrics','compareSubjects','compareReasons'])admin$(id).replaceChildren();}
function renderComparison(){clearComparison();if(!centralAdminData)return;const a=admin$('compareBase').value,b=admin$('compareTarget').value,msg=admin$('compareMessage');if(!a||!b||a===b){msg.textContent='Seleccione dos cuatrimestres distintos.';return;}
 const d=calculateComparison(adminRecords(),a,b);msg.textContent=`Base: ${a} · Comparado: ${b}. N/D: periodo base sin registros para ese indicador.`;
 const incomplete=(centralAdminData.periods||[]).filter(p=>[a,b].includes(p.name)&&String(p.ends_on).slice(0,10)>=new Intl.DateTimeFormat('en-CA',{timeZone:institutionalTimezone}).format(new Date()));if(incomplete.length)msg.textContent+=' Advertencia: periodo aún no concluido; comparación parcial.';
 for(const [id,rows] of [['compareMetrics',d.metrics],['compareSubjects',d.subjects],['compareReasons',d.reasons]]){const body=admin$(id);if(!rows.length){const td=body.insertRow().insertCell();td.colSpan=5;td.textContent='Sin registros.';}for(const x of rows){const time=id==='compareMetrics'&&x.name==='Tiempo de atención';const fmt=n=>time?(n<0?'−':'')+fmtAdmin(Math.abs(n)):String(n);const tr=body.insertRow();for(const v of [x.name,fmt(x.base),fmt(x.target),(x.difference>0?'+':'')+fmt(x.difference),x.percent===null?'N/D':(x.percent>0?'+':'')+x.percent.toLocaleString('es-MX',{maximumFractionDigits:1})+' %'])tr.insertCell().textContent=v;}}
}
document.addEventListener('DOMContentLoaded',()=>{for(const id of ['compareBase','compareTarget'])admin$(id).addEventListener('change',renderComparison)});
